<script setup lang="ts">
import type { WebsiteTheme } from '@/services/website.service'
defineProps<{ theme: WebsiteTheme; status: string }>()
const emit = defineEmits<{ update: [patch: Partial<WebsiteTheme>] }>()
const palettes = [{ name: 'Sky Tech (Default)', primaryColor: '#0284c7', primaryDark: '#0369a1', accentColor: '#f59e0b' }, { name: 'Indigo Academic', primaryColor: '#4f46e5', primaryDark: '#3730a3', accentColor: '#10b981' }, { name: 'Emerald Vokasi', primaryColor: '#059669', primaryDark: '#065f46', accentColor: '#f97316' }, { name: 'Violet Creative', primaryColor: '#7c3aed', primaryDark: '#5b21b6', accentColor: '#ec4899' }, { name: 'Classic Navy', primaryColor: '#1e3a8a', primaryDark: '#172554', accentColor: '#eab308' }]
function applyPalette(palette: typeof palettes[number]): void { emit('update', { primaryColor: palette.primaryColor, primaryDark: palette.primaryDark, accentColor: palette.accentColor }) }
</script>
<template><div class="space-y-4 text-xs"><div><h4 class="font-bold uppercase tracking-wider text-slate-800">Preset Palet Warna</h4><p class="mt-0.5 text-[11px] text-slate-400">Pilih kombinasi warna profesional yang selaras dengan identitas sekolah</p></div><div class="space-y-2"><button v-for="palette in palettes" :key="palette.name" class="flex w-full items-center justify-between rounded-xl border p-2.5 text-left transition-all" :class="theme.primaryColor === palette.primaryColor ? 'border-sky-500 bg-sky-50/40 ring-2 ring-sky-500/20' : 'border-slate-200 bg-white hover:border-slate-300'" @click="applyPalette(palette)"><span class="font-medium text-slate-800">{{ palette.name }}</span><span class="flex gap-1"><i v-for="color in [palette.primaryColor, palette.primaryDark, palette.accentColor]" :key="color" class="h-4 w-4 rounded-full border border-black/10 shadow-xs" :style="{ backgroundColor: color }" /></span></button></div><div class="space-y-3 border-t border-slate-200 pt-2"><label class="block font-semibold text-slate-700">Font Tipografi<select :value="theme.fontFamily" class="mt-1 w-full rounded-lg border border-slate-200 bg-slate-50 p-2 text-xs font-normal" @change="emit('update', { fontFamily: ($event.target as HTMLSelectElement).value })"><option value="Inter, sans-serif">Inter (Modern & Bersih)</option><option value="system-ui, sans-serif">System Default</option></select></label><div><span class="mb-1 block font-semibold text-slate-700">Kelengkungan Sudut (Corner Radius)</span><div class="grid grid-cols-4 gap-1.5"><button v-for="radius in (['sm','md','lg','full'] as const)" :key="radius" class="rounded-lg border py-1.5 text-[10px] font-bold uppercase" :class="theme.borderRadius === radius ? 'border-sky-600 bg-sky-600 text-white shadow-xs' : 'border-slate-200 bg-slate-50 text-slate-600 hover:bg-slate-100'" @click="emit('update', { borderRadius: radius })">{{ radius }}</button></div></div><p class="text-[10px] text-slate-400">Status: {{ status }}</p></div></div></template>
